#!/usr/bin/env python3
# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""Safe idempotent section updater for CLAUDE.md and README.md.

Uses HTML comment fences (<!-- synaptory-start --> / <!-- synaptory-end -->)
to manage the synaptory section without touching user-written content.

Also manages a machine-readable state sentinel (<!-- synaptory-state ... -->)
that provides instant pipeline awareness without needing to read pipeline-state.json.

Usage:
    # Update the synaptory fenced section:
    echo "section content" | python3 update_claude_md.py <project_dir> [--file README.md]

    # Read the current sentinel as JSON:
    python3 update_claude_md.py <project_dir> --sentinel-read

    # Write/update the sentinel from JSON stdin:
    echo '{"lifecycle_state":"SPRINT_EXECUTION","current_sprint":2}' | python3 update_claude_md.py <project_dir> --sentinel-write

Behaviors (fenced section):
    - File doesn't exist: creates it with just the fenced section
    - File exists, no fenced block: appends fenced section at end
    - File exists with fenced block: replaces only the fenced content
    - Old-style '# Synaptory Native' header without fences: migrates to fenced block
    - Atomic write via temp file + os.replace()

Behaviors (sentinel):
    - read: finds <!-- synaptory-state\\n...\\n--> anywhere in the file, returns parsed dict
    - write: merges new key-value pairs into existing sentinel (preserves unmentioned keys),
             or appends a new sentinel block if none exists
    - Sentinel is a standalone HTML comment, invisible in rendered markdown (~150 bytes)
"""
from __future__ import annotations

import json
import os
import re
import sys

FENCE_START = "<!-- synaptory-start -->"
FENCE_END = "<!-- synaptory-end -->"

# Regex to match the full fenced block (start fence, content, end fence)
FENCE_PATTERN = re.compile(
    r"<!-- synaptory-start -->.*?<!-- synaptory-end -->",
    re.DOTALL,
)

# Old-style header pattern for migration
OLD_HEADER_PATTERN = re.compile(
    r"(^|\n)(# Synaptory Native\n.*)",
    re.DOTALL,
)

# Sentinel block: <!-- synaptory-state\nkey: value\n...-->
SENTINEL_PATTERN = re.compile(
    r"<!-- synaptory-state\n(.*?)-->",
    re.DOTALL,
)


def _wrap_in_fences(content: str) -> str:
    """Wrap content in synaptory fence markers."""
    return "{start}\n{content}\n{end}".format(
        start=FENCE_START,
        content=content.rstrip(),
        end=FENCE_END,
    )


def _migrate_old_header(text: str) -> str:
    """If old-style '# Synaptory Native' exists without fences, wrap it."""
    if FENCE_START in text:
        return text
    match = OLD_HEADER_PATTERN.search(text)
    if match:
        old_section = match.group(2)
        wrapped = _wrap_in_fences(old_section)
        text = text[: match.start(2)] + wrapped + text[match.end(2) :]
    return text


def update_section(project_dir: str, new_content: str, filename: str = "CLAUDE.md") -> None:
    """Replace the synaptory section in the target file.

    Args:
        project_dir: Path to the project root directory.
        new_content: New content for the synaptory section.
        filename: Target file name (CLAUDE.md or README.md).
    """
    filepath = os.path.join(project_dir, filename)
    wrapped = _wrap_in_fences(new_content)

    if not os.path.exists(filepath):
        _atomic_write(filepath, wrapped + "\n")
        return

    with open(filepath, "r", encoding="utf-8") as f:
        text = f.read()

    # Migrate old-style header if present
    text = _migrate_old_header(text)

    if FENCE_PATTERN.search(text):
        # Replace existing fenced block
        updated = FENCE_PATTERN.sub(wrapped, text, count=1)
    else:
        # Append fenced block at end
        separator = "\n\n" if text and not text.endswith("\n\n") else ("\n" if text and not text.endswith("\n") else "")
        updated = text + separator + wrapped + "\n"

    # Ensure file ends with a newline
    if not updated.endswith("\n"):
        updated += "\n"

    _atomic_write(filepath, updated)


def _atomic_write(filepath: str, content: str) -> None:
    """Write content atomically using a temp file and os.replace()."""
    dirpath = os.path.dirname(filepath) or "."
    basename = os.path.basename(filepath)
    tmp_path = os.path.join(dirpath, ".{}.tmp".format(basename))
    try:
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(content)
        os.replace(tmp_path, filepath)
    except Exception:
        # Clean up temp file on failure
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise


def _parse_sentinel(body: str) -> dict:
    """Parse YAML-like key: value lines from sentinel body into a dict.

    Supports the v2 flat form (one-level key: value) and the v3 multi-spec
    rollup form which has an indented `specs:` sub-block (design §5.2).
    Indented children of `specs:` are returned as a nested dict at
    `result["specs"][<spec_id>] = "<freeform summary string>"` — the
    summary is intentionally left as a single string because the rollup
    is a read-only display surface, not a parsed structure.
    """
    result: dict = {}
    current_section: str | None = None
    for raw in body.splitlines():
        if not raw.strip() or raw.strip().startswith("#"):
            continue
        # Indented child (sub-key of the most recent block-style key like `specs:`)
        indent = len(raw) - len(raw.lstrip())
        line = raw.strip()
        if indent > 0 and current_section is not None and ":" in line:
            key, _, value = line.partition(":")
            result.setdefault(current_section, {})[key.strip()] = value.strip()
            continue
        # Top-level key
        if ":" in line:
            key, _, value = line.partition(":")
            key = key.strip()
            value = value.strip()
            if not value:
                # Start of a block-style key (e.g. `specs:` with indented body)
                result[key] = {}
                current_section = key
            else:
                result[key] = value
                current_section = None
    return result


def _format_sentinel(sentinel_dict: dict) -> str:
    """Format a dict as a synaptory-state sentinel block.

    Nested dict values are rendered as indented YAML sub-blocks; this is
    the canonical form for the multi-spec rollup (design §5.2). Scalar
    values use the legacy `key: value` flat form.
    """
    lines = ["<!-- synaptory-state"]
    for key, value in sentinel_dict.items():
        if isinstance(value, dict):
            lines.append("{}:".format(key))
            for sub_key, sub_val in value.items():
                lines.append("  {}: {}".format(sub_key, sub_val))
        else:
            lines.append("{}: {}".format(key, value))
    lines.append("-->")
    return "\n".join(lines)


def build_rollup_sentinel(project_dir: str) -> dict:
    """Read pipeline-state.json and build the canonical sentinel dict.

    Multi-spec (v3): emits `active_spec` plus an indented `specs:` block
                     where each entry is a one-line summary
                     `STATE sprint=N last_agent=<id>` (design §5.2).
    Single-spec (v2): emits the legacy flat fields (lifecycle_state,
                      current_sprint, last_agent, last_updated).

    Returns {} if no state file exists.
    """
    from datetime import datetime, timezone

    try:
        import spec_state
    except ImportError:  # pragma: no cover — same-dir import
        spec_state = None  # type: ignore

    if spec_state is None:
        return {}

    full = spec_state.read_full_state(project_dir)
    if not full:
        return {}

    now = datetime.now(timezone.utc).isoformat()
    last_agent = _detect_last_agent_filename(project_dir, spec_state=spec_state, full=full)

    if spec_state.is_multispec(full):
        out: dict = {
            "last_updated": now,
            "active_spec": full.get("active_spec", ""),
            "specs": {},
        }
        for sid, sub in (full.get("specs") or {}).items():
            lifecycle = sub.get("lifecycle_state", "?")
            sprint = sub.get("current_sprint", "?")
            la = last_agent.get(sid, "<none>")
            out["specs"][sid] = f"{lifecycle} sprint={sprint} last_agent={la}"
        return out

    # v2 flat
    return {
        "last_updated": now,
        "lifecycle_state": full.get("lifecycle_state", ""),
        "current_sprint": full.get("current_sprint", 0),
        "last_agent": last_agent.get("__global__", "<none>"),
    }


def _detect_last_agent_filename(project_dir: str, *, spec_state, full: dict) -> dict:
    """Return {spec_id: last_agent_filename} or {"__global__": ...} for v2.

    Best-effort: scans the receipts directory for the most recently modified
    JSON. Names match the receipt-protocol convention
    `{story_id}-{role_abbrev}.json` and we strip the `.json` suffix.
    """
    result: dict = {}
    if spec_state.is_multispec(full):
        base = os.path.join(project_dir, ".synaptory", ".orchestrator", "specs")
        if os.path.isdir(base):
            for sid in os.listdir(base):
                rdir = os.path.join(base, sid, "receipts")
                last = _newest_receipt_basename(rdir)
                if last:
                    result[sid] = last
        return result

    rdir = os.path.join(project_dir, ".synaptory", ".orchestrator", "receipts")
    last = _newest_receipt_basename(rdir)
    if last:
        result["__global__"] = last
    return result


def _newest_receipt_basename(rdir: str) -> str | None:
    try:
        entries = [f for f in os.listdir(rdir) if f.endswith(".json")]
    except OSError:
        return None
    if not entries:
        return None
    entries.sort(
        key=lambda f: os.path.getmtime(os.path.join(rdir, f)),
        reverse=True,
    )
    return entries[0][:-5]  # strip `.json`


def write_sentinel_rollup(project_dir: str, filename: str = "CLAUDE.md") -> dict:
    """Rebuild the entire sentinel from pipeline-state.json and write it.

    This is the canonical multi-spec write path — instead of merging
    individual keys (the legacy `write_sentinel` API), it re-renders the
    sentinel as a complete rollup. Returns the dict that was written.
    """
    rollup = build_rollup_sentinel(project_dir)
    if not rollup:
        return {}
    # Force a full replacement: strip any existing sentinel first so the
    # merge-preserving behavior of write_sentinel doesn't bring stale keys
    # back. We do this in one atomic write at the end.
    filepath = os.path.join(project_dir, filename)
    text = ""
    if os.path.exists(filepath):
        with open(filepath, "r", encoding="utf-8") as f:
            text = f.read()
    text = SENTINEL_PATTERN.sub("", text).rstrip() + ("\n" if text else "")
    new_block = _format_sentinel(rollup)
    fence_match = FENCE_PATTERN.search(text) if text else None
    if fence_match:
        insert_at = fence_match.end()
        updated = text[:insert_at] + "\n" + new_block + "\n" + text[insert_at:]
    elif text:
        sep = "\n\n" if not text.endswith("\n\n") else ""
        updated = text + sep + new_block + "\n"
    else:
        updated = new_block + "\n"
    if not updated.endswith("\n"):
        updated += "\n"
    _atomic_write(filepath, updated)
    return rollup


def read_sentinel(project_dir: str, filename: str = "CLAUDE.md") -> dict:
    """Read the synaptory-state sentinel from the file.

    Returns the sentinel as a dict, or {} if not found or file doesn't exist.
    """
    filepath = os.path.join(project_dir, filename)
    if not os.path.exists(filepath):
        return {}
    with open(filepath, "r", encoding="utf-8") as f:
        text = f.read()
    match = SENTINEL_PATTERN.search(text)
    if not match:
        return {}
    return _parse_sentinel(match.group(1))


def write_sentinel(
    project_dir: str,
    sentinel_dict: dict,
    filename: str = "CLAUDE.md",
) -> None:
    """Write / update the synaptory-state sentinel in the file.

    Merges new key-value pairs into the existing sentinel (unknown keys are
    preserved). If no sentinel exists, appends a new one at the end of the
    file. Atomic write via temp file + os.replace().
    """
    filepath = os.path.join(project_dir, filename)

    if not os.path.exists(filepath):
        # Nothing to anchor to — create a minimal file with just the sentinel
        _atomic_write(filepath, _format_sentinel(sentinel_dict) + "\n")
        return

    with open(filepath, "r", encoding="utf-8") as f:
        text = f.read()

    match = SENTINEL_PATTERN.search(text)
    if match:
        # Merge: existing values are overwritten by new values; extra existing keys kept
        existing = _parse_sentinel(match.group(1))
        existing.update(sentinel_dict)
        new_block = _format_sentinel(existing)
        updated = text[: match.start()] + new_block + text[match.end() :]
    else:
        # No sentinel found — append after fenced block (or at end of file)
        new_block = _format_sentinel(sentinel_dict)
        fence_match = FENCE_PATTERN.search(text)
        if fence_match:
            insert_at = fence_match.end()
            updated = text[:insert_at] + "\n" + new_block + "\n" + text[insert_at:]
        else:
            separator = "\n\n" if text and not text.endswith("\n\n") else ("\n" if text and not text.endswith("\n") else "")
            updated = text + separator + new_block + "\n"

    if not updated.endswith("\n"):
        updated += "\n"

    _atomic_write(filepath, updated)


def main() -> None:
    if len(sys.argv) < 2:
        print(
            "Usage:\n"
            "  echo 'content' | python3 update_claude_md.py <project_dir> [--file FILENAME]\n"
            "  python3 update_claude_md.py <project_dir> --sentinel-read\n"
            "  echo '{\"lifecycle_state\":\"SPRINT_EXECUTION\"}' | python3 update_claude_md.py <project_dir> --sentinel-write",
            file=sys.stderr,
        )
        sys.exit(1)

    project_dir = sys.argv[1]
    filename = "CLAUDE.md"

    # Parse --file argument
    if "--file" in sys.argv:
        idx = sys.argv.index("--file")
        if idx + 1 < len(sys.argv):
            filename = sys.argv[idx + 1]
        else:
            print("Error: --file requires a filename argument", file=sys.stderr)
            sys.exit(1)

    # --sentinel-read: print current sentinel as JSON
    if "--sentinel-read" in sys.argv:
        try:
            data = read_sentinel(project_dir, filename)
            print(json.dumps(data, indent=2))
        except Exception as e:
            print("Error: {}".format(e), file=sys.stderr)
            sys.exit(1)
        return

    # --rollup-sentinel: regenerate the sentinel from pipeline-state.json
    # (canonical multi-spec write path — see write_sentinel_rollup).
    if "--rollup-sentinel" in sys.argv:
        try:
            rollup = write_sentinel_rollup(project_dir, filename)
            print(json.dumps(rollup, indent=2))
        except Exception as e:
            print("Error: {}".format(e), file=sys.stderr)
            sys.exit(1)
        return

    # --summarize: emit shell-friendly KEY=value lines from pipeline-state.json.
    # Used by shell hooks (synaptory-session-start.sh, synaptory-reanchor.sh, etc.)
    # so they don't need to re-implement nested-JSON parsing in bash.
    if "--summarize" in sys.argv:
        try:
            import spec_state
        except ImportError:
            spec_state = None  # type: ignore
        if spec_state is None:
            print("Error: spec_state module not importable", file=sys.stderr)
            sys.exit(1)
        full = spec_state.read_full_state(project_dir)
        if not full:
            return
        if spec_state.is_multispec(full):
            print("MULTISPEC=1")
            print("BUILD_MODE={}".format(full.get("build_mode", "scrum")))
            print("ACTIVE_SPEC={}".format(full.get("active_spec", "")))
            # Emit each spec's summary in shell-quotable form
            for sid, sub in (full.get("specs") or {}).items():
                safe = sid.replace("-", "_").upper()
                print("SPEC_{}_LIFECYCLE={}".format(safe, sub.get("lifecycle_state", "")))
                print("SPEC_{}_SPRINT={}".format(safe, sub.get("current_sprint", 0)))
        else:
            print("MULTISPEC=0")
            print("BUILD_MODE={}".format(full.get("build_mode", "scrum")))
            print("LIFECYCLE_STATE={}".format(full.get("lifecycle_state", "")))
            print("CURRENT_SPRINT={}".format(full.get("current_sprint", 0)))
            goal = full.get("sprint_goal")
            if goal:
                # Drop newlines; goal is single-line in the shell summary.
                print("SPRINT_GOAL={}".format(str(goal).replace("\n", " ")))
        return

    # --sentinel-write: read JSON from stdin, merge into sentinel
    if "--sentinel-write" in sys.argv:
        raw = sys.stdin.read()
        if not raw.strip():
            print("Error: no JSON provided on stdin", file=sys.stderr)
            sys.exit(1)
        try:
            sentinel_dict = json.loads(raw)
            write_sentinel(project_dir, sentinel_dict, filename)
        except Exception as e:
            print("Error: {}".format(e), file=sys.stderr)
            sys.exit(1)
        return

    # Default: update fenced section content from stdin
    content = sys.stdin.read()
    if not content.strip():
        print("Error: no content provided on stdin", file=sys.stderr)
        sys.exit(1)

    try:
        update_section(project_dir, content, filename)
    except Exception as e:
        print("Error: {}".format(e), file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
